const listFraudCases = `-- name: ListFraudCases :many

SELECT t.id AS transfer_id,
       coalesce((t.risk->>'score')::float8, 0)::float8 AS score,
       coalesce(f.closed_at, t.created_at)::timestamptz AS sort_time
FROM transfers t LEFT JOIN fraud_cases f ON f.transfer_id = t.id
WHERE CASE $1::text
        WHEN 'open' THEN t.status = 'held_for_review' AND f.transfer_id IS NULL
        WHEN 'in_review' THEN t.status = 'held_for_review' AND f.status = 'in_review'
        ELSE f.status = $1::text
      END
  AND (CASE WHEN $1::text IN ('open', 'in_review')
            THEN (coalesce((t.risk->>'score')::float8, 0), t.id) < ($2::float8, $3::uuid)
            ELSE (f.closed_at, t.id) < ($4::timestamptz, $3::uuid) END)
ORDER BY CASE WHEN $1::text IN ('open', 'in_review') THEN coalesce((t.risk->>'score')::float8, 0) END DESC NULLS LAST,
         f.closed_at DESC NULLS LAST, t.id DESC
LIMIT $5
`

type ListFraudCasesParams struct {
	Status     string
	AfterScore float64
	AfterID    uuid.UUID
	AfterTime  time.Time
	PageSize   int32
}

type ListFraudCasesRow struct {
	TransferID uuid.UUID
	Score      float64
	SortTime   time.Time
}

// ---------------------------------------------------------------- fraud cases
// Held transfers (open or in review) highest risk first, or closed cases newest first. status
// is 'open', 'in_review', 'released' or 'rejected'.
func (q *Queries) ListFraudCases(ctx context.Context, arg ListFraudCasesParams) ([]ListFraudCasesRow, error) {
	rows, err := q.db.Query(ctx, listFraudCases,
		arg.Status,
		arg.AfterScore,
		arg.AfterID,
		arg.AfterTime,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListFraudCasesRow{}
	for rows.Next() {
		var i ListFraudCasesRow
		if err := rows.Scan(&i.TransferID, &i.Score, &i.SortTime); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

