const searchCustomers = `-- name: SearchCustomers :many

SELECT u.id, u.first_name, u.last_name, u.email, u.phone, u.nemtag, u.kyc_tier, u.frozen_at, u.created_at
FROM users u
WHERE (u.created_at, u.id) < ($1::timestamptz, $2::uuid)
  AND (
    lower(u.first_name || ' ' || u.last_name) LIKE '%' || $3::text || '%'
    OR u.email LIKE $3::text || '%'
    OR u.phone LIKE '%' || $3::text || '%'
    OR u.nemtag LIKE ltrim($3::text, chr(64)) || '%'
    OR EXISTS (SELECT 1 FROM customer_accounts a WHERE a.user_id = u.id AND a.account_number = $3::text)
  )
ORDER BY u.created_at DESC, u.id DESC
LIMIT $4
`

type SearchCustomersParams struct {
	AfterTime time.Time
	AfterID   uuid.UUID
	Term      string
	PageSize  int32
}

type SearchCustomersRow struct {
	ID        uuid.UUID
	FirstName string
	LastName  string
	Email     string
	Phone     string
	Nemtag    *string
	KycTier   int16
	FrozenAt  *time.Time
	CreatedAt time.Time
}

// ---------------------------------------------------------------- customers
// By name, email, phone, nemtag or account number (ADM-3), newest first. The term arrives
// lower-cased and LIKE-escaped; the first page passes now() and the max UUID.
func (q *Queries) SearchCustomers(ctx context.Context, arg SearchCustomersParams) ([]SearchCustomersRow, error) {
	rows, err := q.db.Query(ctx, searchCustomers,
		arg.AfterTime,
		arg.AfterID,
		arg.Term,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchCustomersRow{}
	for rows.Next() {
		var i SearchCustomersRow
		if err := rows.Scan(
			&i.ID,
			&i.FirstName,
			&i.LastName,
			&i.Email,
			&i.Phone,
			&i.Nemtag,
			&i.KycTier,
			&i.FrozenAt,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

