const trialBalance = `-- name: TrialBalance :many
SELECT p.currency,
       coalesce(sum(CASE WHEN p.amount_minor < 0 THEN -p.amount_minor END), 0)::bigint AS total_debits,
       coalesce(sum(CASE WHEN p.amount_minor > 0 THEN p.amount_minor END), 0)::bigint AS total_credits,
       coalesce(sum(p.amount_minor), 0)::bigint AS net,
       count(DISTINCT p.account_id)::int AS accounts
FROM postings p WHERE p.created_at <= $1::timestamptz
GROUP BY p.currency ORDER BY p.currency
`

type TrialBalanceRow struct {
	Currency     string
	TotalDebits  int64
	TotalCredits int64
	Net          int64
	Accounts     int32
}

// Per currency: every posting up to as_of. Debits are the negative postings, credits the
// positive ones; the ledger is sound only when they cancel exactly.
func (q *Queries) TrialBalance(ctx context.Context, asOf time.Time) ([]TrialBalanceRow, error) {
	rows, err := q.db.Query(ctx, trialBalance, asOf)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TrialBalanceRow{}
	for rows.Next() {
		var i TrialBalanceRow
		if err := rows.Scan(
			&i.Currency,
			&i.TotalDebits,
			&i.TotalCredits,
			&i.Net,
			&i.Accounts,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

